### Python

```python
import sys


# 求字典序最大的数组
def solve_case(n, k, arr):
    groups = [[] for _ in range(k)]

    # 按下标分组，这里使用 0 下标，按 i % k 分组
    for i in range(n):
        groups[i % k].append(arr[i])

    # 每组降序排序
    for i in range(k):
        groups[i].sort(reverse=True)

    # 记录每组当前取到哪个元素
    idx = [0] * k
    res = [0] * n

    # 按原位置顺序回填，每次放当前组最大的剩余元素
    for i in range(n):
        g = i % k
        res[i] = groups[g][idx[g]]
        idx[g] += 1

    return res


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
    p = 1
    ans = []

    for _ in range(t):
        n = data[p]
        k = data[p + 1]
        p += 2
        arr = data[p:p + n]
        p += n

        res = solve_case(n, k, arr)
        ans.append(" ".join(map(str, res)))

    sys.stdout.write("\n".join(ans))


if __name__ == "__main__":
    main()
```

### Java

```java
import java.io.*;
import java.util.*;


public class Main {

    // 求字典序最大的数组
    static int[] solveCase(int n, int k, int[] arr) {
        ArrayList<Integer>[] groups = new ArrayList[k];
        for (int i = 0; i < k; i++) {
            groups[i] = new ArrayList<>();
        }

        // 按下标分组
        for (int i = 0; i < n; i++) {
            groups[i % k].add(arr[i]);
        }

        // 每组降序排序
        for (int i = 0; i < k; i++) {
            groups[i].sort(Collections.reverseOrder());
        }

        int[] idx = new int[k];
        int[] res = new int[n];

        // 按位置顺序回填
        for (int i = 0; i < n; i++) {
            int g = i % k;
            res[i] = groups[g].get(idx[g]);
            idx[g]++;
        }

        return res;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder sb = new StringBuilder();

        int t = fs.nextInt();
        while (t-- > 0) {
            int n = fs.nextInt();
            int k = fs.nextInt();

            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = fs.nextInt();
            }

            int[] res = solveCase(n, k, arr);

            for (int i = 0; i < n; i++) {
                if (i > 0) sb.append(' ');
                sb.append(res[i]);
            }
            sb.append('\n');
        }

        System.out.print(sb.toString());
    }

    // 由于数据较大，使用较快的输入方式
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }
}
