#include <bits/stdc++.h>
using namespace std;


// 求字典序最大的数组
vector<long long> solve_case(int n, int k, const vector<long long>& arr) {
    vector<vector<long long>> groups(k);

    // 按下标分组
    for (int i = 0; i < n; i++) {
        groups[i % k].push_back(arr[i]);
    }

    // 每组降序排序
    for (int i = 0; i < k; i++) {
        sort(groups[i].begin(), groups[i].end(), greater<long long>());
    }

    vector<int> idx(k, 0);
    vector<long long> res(n);

    // 按位置顺序回填
    for (int i = 0; i < n; i++) {
        int g = i % k;
        res[i] = groups[g][idx[g]];
        idx[g]++;
    }

    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int n, k;
        cin >> n >> k;

        vector<long long> arr(n);
        for (int i = 0; i < n; i++) {
            cin >> arr[i];
        }

        vector<long long> res = solve_case(n, k, arr);

        for (int i = 0; i < n; i++) {
            if (i) cout << ' ';
            cout << res[i];
        }
        cout << '\n';
    }

    return 0;
}
